const monsters = [
  'Vampire', 'Ghost', 'Pumpkin', 'Strawman', 'Red Monster', 'Blue Monster',
  'Frankenstein', 'Witch', 'Ghoul', 'Gravestone', 'Devil', 'Alien',
  'Werewolf', 'Zombie', 'Mummy', 'Skeleton', 'Banshee', 'Phantom',
  'Reaper', 'Poltergeist', 'Gremlin', 'Goblin', 'Troll', 'Bat',
  'Dracula', 'Jack-o-Lantern', 'Haunted Tree', 'Mad Scientist', 'Spider',
  'Black Cat', 'Cerberus', 'Gorgon', 'Cyclops', 'Harpy', 'Chupacabra',
  'Headless Horseman', 'Beelzebub', 'Kraken', 'Sea Monster', 'Baba Yaga',
  'Wendigo', 'Mothman', 'Sknin Walker', 'Lich', 'Demon', 'Shadow Creature',
  'Swamp Monster', 'Grim Reaper', 'Clown', 'Phantom Knight', 'Siren'
];

const randomIndex = Math.floor(Math.random() * monsters.length);

// Return a single string as a JSON object
return [{
  json: { character: monsters[randomIndex] }
}];
